import re
from collections import Counter

LOG_PATTERN = re.compile(r'(?P<ip>\S+) - - \[(?P<time>.*?)\] "(?P<request>.*?)" (?P<status>\d+) (?P<size>\d+)')

def parse_line(line):
    match = LOG_PATTERN.match(line)
    if not match:
        return None
    return match.groupdict()

def count_status_codes(filepath):
    counter = Counter()
    with open(filepath) as f:
        for line in f:
            parsed = parse_line(line)
            if parsed:
                counter[parsed['status']] += 1
    return counter

if __name__ == '__main__':
    counts = count_status_codes('access.log')
    for status, count in counts.most_common():
        print(f"{status}: {count}")

import statistics

def compute_summary(values):
    return {
        'count': len(values),
        'mean': statistics.mean(values),
        'median': statistics.median(values),
        'stdev': statistics.stdev(values) if len(values) > 1 else 0,
        'min': min(values),
        'max': max(values),
    }

def summarize_column(records, column):
    values = [r[column] for r in records if column in r]
    return compute_summary(values)

