interface InitOptions {
  name: string;
  directory: string;
}

export function initProject(options: InitOptions): void {
  const targetDir = path.join(options.directory, options.name);

  if (fs.existsSync(targetDir)) {
    console.error(`Directory ${targetDir} already exists`);
    process.exit(1);
  }

  fs.mkdirSync(targetDir, { recursive: true });

  const configContent = JSON.stringify({
    name: options.name,
    version: '0.1.0'
  }, null, 2);

  fs.writeFileSync(path.join(targetDir, 'config.json'), configContent);

  console.log(`Initialized project ${options.name} in ${targetDir}`);
}

