object MarkupStripper {
    private val tagRegex = Regex("<[^>]+>")
    private val entityMap = mapOf(
        "&amp;" to "&",
        "&lt;" to "<",
        "&gt;" to ">"
    )

    fun strip(html: String): String {
        var result = tagRegex.replace(html, "")
        for ((entity, replacement) in entityMap) {
            result = result.replace(entity, replacement)
        }
        return result.trim()
    }
}

function interpolate(template, context) {
  const pattern = /\{\{\s*([a-zA-Z0-9_.]+)\s*\}\}/g;
  return template.replace(pattern, (match, key) => {
    const parts = key.split('.');
    let value = context;
    for (const part of parts) {
      if (value == null) return match;
      value = value[part];
    }
    return value !== undefined ? String(value) : match;
  });
}

module.exports = { interpolate };

package tokenizer

import (
	"strings"
	"unicode"
)

type Token struct {
	Kind  string
	Value string
}

func Tokenize(input string) []Token {
	var tokens []Token
	var current strings.Builder

	flush := func(kind string) {
		if current.Len() > 0 {
			tokens = append(tokens, Token{Kind: kind, Value: current.String()})
			current.Reset()
		}
	}

	for _, r := range input {
		switch {
		case unicode.IsSpace(r):
			flush("WORD")
		case unicode.IsDigit(r):
			current.WriteRune(r)
		case unicode.IsLetter(r):
			current.WriteRune(r)
		default:
			flush("WORD")
			tokens = append(tokens, Token{Kind: "SYMBOL", Value: string(r)})
		}
	}
	flush("WORD")
	return tokens

}

#[derive(Debug, PartialEq)]
pub struct Version {
    pub major: u32,
    pub minor: u32,
    pub patch: u32,
}

pub fn parse_version(input: &str) -> Option<Version> {
    let parts: Vec<&str> = input.split('.').collect();
    if parts.len() != 3 {
        return None;
    }
    let major = parts[0].parse::<u32>().ok()?;
    let minor = parts[1].parse::<u32>().ok()?;
    let patch = parts[2].parse::<u32>().ok()?;
    Some(Version { major, minor, patch)
}

def parse_ini(text):
    config = {}
    current_section = None
    for raw_line in text.splitlines():
        line = raw_line.strip()
        if not line or line.startswith(';'):
            continue
        if line.startswith('[') and line.endswith(']'):
            current_section = line[1:-1]
            config[current_section] = {}
            continue
        if '=' in line:
            key, value = line.split('=', 1)
            key = key.strip()
            value = value.strip()
            if current_section is None:
                continue
            config[current_section][key] = value
    return config

import re

ABBREVIATIONS = {'Mr.', 'Mrs.', 'Dr.', 'e.g.', 'i.e.'}

def split_sentences(text):
    raw_sentences = re.split(r'(?<=[.!?])\s+', text)
    sentences = []
    buffer = ''
    for chunk in raw_sentences:
        buffer = (buffer + ' ' + chunk).strip() if buffer else chunk
        last_word = buffer.split()[-1] if buffer.split() else ''
        if last_word in ABBREVIATIONS:
            continue
        sentences.append(buffer)
        buffer = ''
    if buffer:
        sentences.append(buffer)
    return sentences

