from datetime import datetime, timedelta

def get_next_run_time(last_run, interval_days):
    return last_run + timedelta(days=interval_days)

def get_missed_runs(last_run, interval_days, now):
    missed = []
    next_run = get_next_run_time(last_run, interval_days)
    while next_run < now:
        missed.append(next_run)
        next_run = get_next_run_time(next_run, interval_days)
    return missed

def should_run_now(last_run, interval_days, now, tolerance_minutes=5):
    next_run = get_next_run_time(last_run, interval_days)
    diff = abs((now - next_run).total_seconds()) / 60
    return diff <= tolerance_minutes

