def convert_to_user_timezone(utc_dt, user_tz_name):
    """Convert a naive UTC datetime to the user's local timezone."""
    utc_zone = pytz.utc
    user_zone = pytz.timezone(user_tz_name)
    localized_utc = utc_dt.replace(tzinfo=utc_zone)
    return localized_utc.astimezone(user_zone)

